// Authored A2 curriculum, Unit 4: present perfect and everyday communication.
final List<Map<String,dynamic>> a2Unit4CourseData = <Map<String,dynamic>>[
  {'id':'A2-U04-L01','level':'A2','title':"Present perfect experiences",'subtitle':'Communication pratique • Leçon 1/50','explanation':"Use the present perfect to talk about life experiences without naming a finished time.",'example':"I have visited Nairobi twice.",'french':"J’ai visité Nairobi deux fois.",'question':"Which sentence describes experience?",'options':["I have visited Nairobi.","I visit Nairobi yesterday.","I have visit Nairobi."],'answer':0,'correction':"Have visited is the correct present perfect form.",'unit':4,'phase':0},
  {'id':'A2-U04-L02','level':'A2','title':"Ever in questions",'subtitle':'Communication pratique • Leçon 2/50','explanation':"Use Have you ever + past participle to ask about experience.",'example':"Have you ever ridden a horse?",'french':"As-tu déjà monté à cheval ?",'question':"Complete: Have you ever ___ sushi?",'options':["eat","ate","eaten"],'answer':2,'correction':"After have, use the past participle eaten.",'unit':4,'phase':0},
  {'id':'A2-U04-L03','level':'A2','title':"Regular past participles",'subtitle':'Communication pratique • Leçon 3/50','explanation':"Most regular verbs form the past participle with -ed.",'example':"She has cleaned her room.",'french':"Elle a nettoyé sa chambre.",'question':"Past participle of clean?",'options':["cleaned","cleaning","cleans"],'answer':0,'correction':"Cleaned is the regular past participle.",'unit':4,'phase':0},
  {'id':'A2-U04-L04','level':'A2','title':"Irregular past participles",'subtitle':'Communication pratique • Leçon 4/50','explanation':"Learn common irregular participles such as written, seen, and gone.",'example':"We have seen that film.",'french':"Nous avons vu ce film.",'question':"Past participle of write?",'options':["wrote","written","writing"],'answer':1,'correction':"Written is the past participle.",'unit':4,'phase':0},
  {'id':'A2-U04-L05','level':'A2','title':"Already and yet",'subtitle':'Communication pratique • Leçon 5/50','explanation':"Use already in affirmative sentences and yet in questions or negatives.",'example':"I have already eaten, but he hasn’t eaten yet.",'french':"J’ai déjà mangé, mais lui n’a pas encore mangé.",'question':"Choose the correct sentence.",'options':["I have yet finished.","I have already finished.","I already have finish."],'answer':1,'correction':"Already fits the affirmative sentence.",'unit':4,'phase':0},
  {'id':'A2-U04-L06','level':'A2','title':"Just for recent actions",'subtitle':'Communication pratique • Leçon 6/50','explanation':"Use just with present perfect for something that happened a moment ago.",'example':"The bus has just arrived.",'french':"Le bus vient d’arriver.",'question':"The train has ___ left.",'options':["just","yet","ever"],'answer':0,'correction':"Just indicates a very recent action.",'unit':4,'phase':0},
  {'id':'A2-U04-L07','level':'A2','title':"Never for no experience",'subtitle':'Communication pratique • Leçon 7/50','explanation':"Use never to say an experience has not happened.",'example':"I have never flown in a plane.",'french':"Je n’ai jamais pris l’avion.",'question':"Which word means « jamais » here?",'options':["never","already","since"],'answer':0,'correction':"Never expresses no experience.",'unit':4,'phase':0},
  {'id':'A2-U04-L08','level':'A2','title':"For and since",'subtitle':'Communication pratique • Leçon 8/50','explanation':"Use for with a duration and since with a starting point.",'example':"I have lived here for two years.",'french':"J’habite ici depuis deux ans.",'question':"Choose the duration phrase.",'options':["since Monday","for three weeks","since 2022"],'answer':1,'correction':"For three weeks names a duration.",'unit':4,'phase':0},
  {'id':'A2-U04-L09','level':'A2','title':"Present perfect or past simple",'subtitle':'Communication pratique • Leçon 9/50','explanation':"Use past simple with finished times and present perfect when the exact time is not stated.",'example':"I saw her yesterday, but I have seen her before.",'french':"Je l’ai vue hier, mais je l’ai déjà vue auparavant.",'question':"Which phrase names a finished time?",'options':["ever","yesterday","before"],'answer':1,'correction':"Yesterday normally uses past simple.",'unit':4,'phase':0},
  {'id':'A2-U04-L10','level':'A2','title':"Experience questions",'subtitle':'Communication pratique • Leçon 10/50','explanation':"Ask about experience with Have you ever + past participle.",'example':"Have you ever slept in a tent?",'french':"As-tu déjà dormi dans une tente ?",'question':"Choose the correct question.",'options':["Did you ever went camping?","Have you ever gone camping?","Have you ever go camping?"],'answer':1,'correction':"Have + past participle forms the question.",'unit':4,'phase':0},
  {'id':'A2-U04-L11','level':'A2','title':"Making appointments",'subtitle':'Communication pratique • Leçon 11/50','explanation':"Use polite phrases to arrange a time with a professional.",'example':"Could I make an appointment for Friday?",'french':"Pourrais-je prendre rendez-vous pour vendredi ?",'question':"Which is a polite request?",'options':["I want appointment now.","Could I make an appointment?","Appointment me."],'answer':1,'correction':"Could I…? is a polite request.",'unit':4,'phase':0},
