  {'id':'A2-U04-L18','level':'A2','title':"At the doctor",'subtitle':'Communication pratique • Leçon 18/50','explanation':"Describe symptoms and answer simple questions.",'example':"How long have you had the pain?",'french':"Depuis combien de temps avez-vous cette douleur ?",'question':"Which question asks about duration?",'options':["How long have you had it?","How many pain?","Where time pain?"],'answer':0,'correction':"How long asks about duration.",'unit':4,'phase':0},
